import { useEffect, useState } from 'react'
import { supabase, nuvem } from '../servicos/nuvem.js'
import Admin from './Admin.jsx'
import Wordmark from '../componentes/Wordmark.jsx'

/** Admin do LOMBADA na nuvem: entra com o login da equipe (o mesmo do Miolo) e opera direto nas tabelas. */
export default function AdminNuvem({ catalogoPadrao }) {
  const [sessao, setSessao] = useState(undefined)
  const [email, setEmail] = useState(''); const [senha, setSenha] = useState(''); const [erro, setErro] = useState('')
  const [autores, setAutores] = useState([])
  const [leitores, setLeitores] = useState([])
  const [sugestoes, setSugestoes] = useState([])
  const [catalogo, setCatalogo] = useState(null)
  const [codigos, setCodigos] = useState({})
  const [config, setConfig] = useState({})
  const [envios, setEnvios] = useState([])
  const [aulasEm, setAulasEm] = useState(null)
  const [amazon, setAmazon] = useState({}) // asin -> última leitura
  const [boasVindas, setBoasVindas] = useState([]) // fila do acesso pela compra / convite

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSessao(data.session || null))
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSessao(s || null))
    return () => sub.subscription.unsubscribe()
  }, [])

  async function carregar() {
    const [a, l, s, c, cfg, env] = await Promise.all([
      supabase.from('lombada_autores').select('id, email, whatsapp, slug, dados, criado_em, atualizado_em').order('atualizado_em', { ascending: false }),
      supabase.from('lombada_leitores').select('*').order('data', { ascending: false }),
      supabase.from('lombada_sugestoes').select('*').order('data', { ascending: false }),
      nuvem.catalogo(),
      supabase.from('lombada_config').select('chave, valor'),
      supabase.from('lombada_envios').select('*').order('criado_em', { ascending: false }).limit(300),
    ])
    setConfig(Object.fromEntries((cfg.data || []).map((r) => [r.chave, r.valor])))
    supabase.from('lombada_amazon').select('asin, ranking, nota, avaliacoes, lido_em').order('lido_em', { ascending: false }).limit(2000).then(({ data }) => { const m = {}; for (const r of data || []) if (!m[r.asin]) m[r.asin] = r; setAmazon(m) })
    setEnvios(env.data || [])
    supabase.from('lombada_boas_vindas').select('*').order('criado_em', { ascending: false }).limit(200).then(({ data }) => setBoasVindas(data || []))
    setAulasEm(c?.aulas?.SINCRONIZACAO?.em || null)
    const lista = (a.data || []).map((r) => ({ ...r.dados, id: r.id, email: r.email, whatsapp: r.whatsapp || r.dados?.whatsapp, _linha: { criado_em: r.criado_em, atualizado_em: r.atualizado_em } }))
    setAutores(lista)
    const pares = await Promise.all(lista.map(async (x) => [x.id, await nuvem.codigoAtual(x.id).catch(() => null)]))
    setCodigos(Object.fromEntries(pares.filter(([, c]) => c)))
    setLeitores(l.data || [])
    setSugestoes((s.data || []).map((x) => ({ ...x, autorId: x.autor_id })))
    setCatalogo({ acoes: c?.acoes || catalogoPadrao.acoes, modelos: c?.modelos || catalogoPadrao.modelos, oportunidades: c?.oportunidades || catalogoPadrao.oportunidades })
  }
  useEffect(() => { if (sessao) carregar() }, [sessao]) // eslint-disable-line react-hooks/exhaustive-deps

  async function entrar(e) {
    e.preventDefault(); setErro('')
    const { error } = await supabase.auth.signInWithPassword({ email, password: senha })
    if (error) setErro('E-mail ou senha não conferem. Use o seu login do Miolo.')
  }

  // ---- ações da equipe
  async function atualizarDados(autorId, fn) {
    const atual = autores.find((a) => a.id === autorId); if (!atual) return
    const { _linha, ...dados } = atual
    const novo = fn(dados)
    const { error } = await supabase.from('lombada_autores').update({ dados: novo, atualizado_em: new Date().toISOString() }).eq('id', autorId)
    if (!error) setAutores((l) => l.map((a) => (a.id === autorId ? { ...novo, _linha } : a)))
  }
  async function salvarCatalogo(chave, lista) {
    setCatalogo((c) => ({ ...c, [chave]: lista }))
    await supabase.from('lombada_catalogo').upsert({ chave, dados: lista, atualizado_em: new Date().toISOString() })
  }
  const upsertCat = (chave) => (item) => salvarCatalogo(chave, catalogo[chave].some((x) => x.id === item.id) ? catalogo[chave].map((x) => (x.id === item.id ? item : x)) : [...catalogo[chave], item])
  const removerCat = (chave) => (id) => salvarCatalogo(chave, catalogo[chave].filter((x) => x.id !== id))

  const admin = {
    sugestoes,
    marcarSugestaoLida: async (id) => { await supabase.from('lombada_sugestoes').update({ status: 'lida' }).eq('id', id); setSugestoes((l) => l.map((s) => (s.id === id ? { ...s, status: 'lida' } : s))) },
    salvarAcao: upsertCat('acoes'), excluirAcao: removerCat('acoes'),
    salvarModelo: upsertCat('modelos'),
    excluirModelo: async (id) => { await salvarCatalogo('modelos', catalogo.modelos.filter((m) => m.id !== id && m.variaDe !== id)); await salvarCatalogo('acoes', catalogo.acoes.map((a) => ({ ...a, modeloIds: a.modeloIds.filter((m) => m !== id) }))) },
    salvarOportunidade: upsertCat('oportunidades'), excluirOportunidade: removerCat('oportunidades'),
    alterarCadastro: (autorId, status, observacao) => atualizarDados(autorId, (a) => ({ ...a, cadastro: { ...(a.cadastro || {}), status, observacao: status === 'ajustar' ? observacao : a.cadastro?.observacao, revisadoEm: new Date().toISOString() } })),
    alterarVagas: (autorId, delta) => atualizarDados(autorId, (a) => ({ ...a, vagasLivros: Math.max(1, (Number(a.vagasLivros) || 1) + delta) })),
    alterarAcesso: (autorId, status) => atualizarDados(autorId, (a) => ({ ...a, acesso: { ...(a.acesso || {}), status, ate: status === 'ativo' ? null : a.acesso?.ate } })),
    gerarCodigo: async (autorId) => { const c = await nuvem.gerarCodigo(autorId); setCodigos((m) => ({ ...m, [autorId]: c })); return c },
    definirCodigo: async (autorId, codigo) => { const c = await nuvem.definirCodigo(autorId, codigo); setCodigos((m) => ({ ...m, [autorId]: c })); return c },
    alterarEmail: async (autorId, email) => { const e = await nuvem.alterarEmail(autorId, email); setAutores((l) => l.map((a) => (a.id === autorId ? { ...a, email: e } : a))) },
    codigos,
    onSair: () => supabase.auth.signOut(),
    equipe: sessao?.user?.email,
  }
  const operacao = {
    config, envios, aulasEm,
    definirConfig: async (chave, valor) => {
      const { error } = await supabase.from('lombada_config').upsert({ chave, valor, atualizado_em: new Date().toISOString() })
      if (error) throw new Error(error.message)
      setConfig((c) => ({ ...c, [chave]: valor }))
      return { ok: true }
    },
    simular: () => nuvem.operacao('lombada-semanal', sessao, { dry: '1' }),
    enviarAgora: async () => { const r = await nuvem.operacao('lombada-semanal', sessao); const env = await supabase.from('lombada_envios').select('*').order('criado_em', { ascending: false }).limit(300); setEnvios(env.data || []); return r },
    sincronizarAulas: async () => { const r = await nuvem.operacao('lombada-sync-aulas', sessao); setAulasEm(new Date().toISOString()); return r },
    // acesso pela compra (fila lombada_boas_vindas)
    boasVindas,
    processarBoasVindas: async (dry) => { const r = await nuvem.operacao('lombada-boas-vindas', sessao, dry ? { dry: '1' } : {}); await recarregarBoasVindas(); return r },
    convidar: async (email, nome, whatsapp) => { const r = await nuvem.convidar(email, nome, whatsapp); await recarregarBoasVindas(); await carregar(); return r },
  }
  async function recarregarBoasVindas() {
    const { data } = await supabase.from('lombada_boas_vindas').select('*').order('criado_em', { ascending: false }).limit(200)
    setBoasVindas(data || [])
  }
  const dados = {
    salvoEm: null,
    exportar: () => JSON.stringify({ versao: 1, exportadoEm: new Date().toISOString(), autores, leitores, sugestoes, ...catalogo }, null, 2),
    importar: () => { throw new Error('Na nuvem, a importação é feita pelo time no banco.') },
    redefinir: async () => { if (window.confirm('Voltar o catálogo (ações, textos, oportunidades) para o do código? Os autores não são apagados.')) { await supabase.from('lombada_catalogo').delete().neq('chave', ''); setCatalogo(catalogoPadrao) } },
  }

  if (sessao === undefined) return null
  if (!sessao) {
    return (
      <div className="min-h-screen">
        <div className="border-b-2 border-tinta"><div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center gap-3"><Wordmark tamanho={24} /><span className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Administrador</span></div></div>
        <main className="max-w-md mx-auto px-4 sm:px-6 py-12">
          <h1 className="display text-[32px]">Entrada da equipe</h1>
          <p className="text-[13.5px] text-apoio mt-2">Use o mesmo e-mail e senha do Miolo.</p>
          <form onSubmit={entrar} className="mt-6 grid gap-4">
            <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="e-mail" className="campo" autoComplete="username" />
            <input type="password" required value={senha} onChange={(e) => setSenha(e.target.value)} placeholder="senha" className="campo" autoComplete="current-password" />
            {erro && <p className="text-[13px] font-bold text-alerta">{erro}</p>}
            <button type="submit" className="btn-preto justify-self-start">Entrar</button>
          </form>
        </main>
      </div>
    )
  }
  if (!catalogo) return null
  return <Admin autores={autores} leitores={leitores} acoes={catalogo.acoes} modelos={catalogo.modelos} oportunidades={catalogo.oportunidades} dados={dados} operacao={operacao} uso={{ carregar: (dias) => nuvem.usoResumo(dias) }} amazon={amazon} {...admin} />
}
